      evidence.reason = "malformed-authorization";
      return evidence;
    }

    if (!keyId) {
      evidence.outcome = "rejected";
      evidence.reason = "missing-key-id";
      return evidence;
    }

    if (!ACTIVE_KEYS.has(keyId)) {
      evidence.outcome = "rejected";
      evidence.reason = "unknown-key-id";
      return evidence;
    }

    const key = loadKey(keyId);
    if (!key) {
      evidence.outcome = "rejected";
      evidence.reason = "unknown-key-id";
      return evidence;
    }

    const computedSig = createHmac("sha256", key)
      .update(canonical, "utf8")
      .digest("hex");
    evidence.signature = computedSig;

    if (!parsed.signature.match(/^[0-9a-fA-F]*$/)) {
      evidence.outcome = "rejected";
      evidence.reason = "signature-mismatch";
      return evidence;
    }

    const presentedSig = parsed.signature.toLowerCase();
    try {
      if (timingSafeEqual(Buffer.from(computedSig), Buffer.from(presentedSig))) {
        evidence.outcome = "verified";
      } else {
        evidence.outcome = "rejected";
        evidence.reason = "signature-mismatch";
      }
    } catch {
      evidence.outcome = "rejected";
      evidence.reason = "signature-mismatch";
    }

    return evidence;
  }

  if (!keyId) {
    evidence.outcome = "rejected";
    evidence.reason = "missing-key-id";
    return evidence;
  }

  if (!ACTIVE_KEYS.has(keyId)) {
    evidence.outcome = "rejected";
    evidence.reason = "unknown-key-id";
    return evidence;
  }

  const key = loadKey(keyId);
  if (!key) {
    evidence.outcome = "rejected";
    evidence.reason = "unknown-key-id";
    return evidence;
  }

  evidence.signature = createHmac("sha256", key)
    .update(canonical, "utf8")
    .digest("hex");
  evidence.outcome = "signed";

  return evidence;
}

function main(): void {
  const records = JSON.parse(readFileSync(0, "utf8")) as InputRecord[];

  records.forEach((rec, i) => {
    const evidence = processRecord(rec, i + 1);
    const output: Record<string, unknown> = {
      seq: evidence.seq,
      key_id: evidence.key_id,
      method: evidence.method,
      path: evidence.path,
      outcome: evidence.outcome,
      signature: evidence.signature,
      canonical_sha256: evidence.canonical_sha256,
    };
    if (evidence.reason) {
      output.reason = evidence.reason;
    }
    process.stdout.write(JSON.stringify(output) + "\n");
  });
}

